import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        List<String> sozlar = new ArrayList<>();
        for (String s : in.nextLine().trim().split("\\s+")) sozlar.add(s);

        Map<String, Integer> chastota = new HashMap<>();
        for (String soz : sozlar) chastota.merge(soz, 1, Integer::sum);

        String javob = "-";
        for (String soz : sozlar) {
            if (chastota.get(soz) == 1) javob = soz;
        }
        System.out.println(javob);
    }
}

