#include <map>
#include <sstream>
#include <string>
#include <vector>
using namespace std;

int main() {
    string satr;
    getline(cin, satr);
    istringstream oqim(satr);

    vector<string> sozlar;
    map<string, int> chastota;
    string soz;
    while (oqim >> soz) {
        sozlar.push_back(soz);
        chastota[soz]++;
    }

    string javob = "-";
    for (const string& s : sozlar) {
        if (chastota[s] == 1) javob = s;
    }
    cout << javob << endl;
    return 0;
}

